import {SAVE_KEYS,createSaveOwnership,installSaveStorageGuard} from './expedition-save-ownership.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountSaveOwnership(){
 const owner=createSaveOwnership(globalThis.navigator?.locks),box=document.createElement('aside');box.id='save-ownership';box.className='save-ownership';box.setAttribute('aria-live','polite');document.body.prepend(box);
 let storage,lastOwnRaw=null,queued=false,problem='',guarded=false;const raw=()=>Object.fromEntries(SAVE_KEYS.map(k=>[k,storage.getItem(k)]));
 const render=()=>{const s=owner.state;box.dataset.saveOwnership=s.status;document.body.dataset.saveOwnership=s.status;box.innerHTML='<div><strong tabindex="-1">'+esc(s.status==='writer'?'本页可保存':'本页只读')+'</strong><span> '+esc(s.reason)+'</span></div><div class=bar>'+(s.status==='writer'?'<button data-save-release>释放本页写入权</button>':'<button data-save-reload>重新载入并尝试取得写入权</button>')+'<button data-save-raw>导出当前原始档</button>'+(lastOwnRaw?'<button data-save-last>导出本页最后保存副本</button>':'')+'</div><small>同一来源只允许一个参与保护的页面保存；启用前请关闭或更新旧版本页。旧页面、开发者工具或不参与协议的程序仍可能写入，不能当作跨页事务或安全屏障。</small>'+(problem?'<p role=alert>'+esc(problem)+'</p>':'');};
 owner.subscribe(render);render();await owner.ready;
 try{storage=globalThis.localStorage;installSaveStorageGuard(storage,owner,{onWrite(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;if(owner.state.status==='writer')try{lastOwnRaw=raw();}catch{}});}});guarded=true;}catch{owner.release('存档保护或存储初始化失败，本页只读。请导出可读取内容，再检查浏览器存储或重新载入。');}
 // Snapshot availability is separate from installing the write guard. A single
 // unreadable key must leave the existing recovery UI accessible without writes.
 if(guarded&&owner.state.status==='writer')try{lastOwnRaw=raw();}catch{problem='完整原始副本暂时无法读取，原存档未覆盖。请查看原有存档恢复提示，或修复浏览器存储读取后重新载入。';}
 const download=(value,label)=>{const url=URL.createObjectURL(new Blob([JSON.stringify({format:'wod-raw-storage-snapshot',version:1,label,createdAt:new Date().toISOString(),raw:value,note:'原始四键排查副本，保留字符串；不是可直接恢复的整档备份。不会自动覆盖或合并。'},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='wod-'+label+'-raw-storage.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 box.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-save-release')){owner.release();return;}if(b.hasAttribute('data-save-reload')){location.reload();return;}try{if(b.hasAttribute('data-save-last')){if(!lastOwnRaw)throw Error('没有本页保存副本');download(lastOwnRaw,'last-own');}else if(b.hasAttribute('data-save-raw')){if(!storage)throw Error('浏览器存储不可读取');download(raw(),'current');}}catch(error){problem='导出失败：'+error.message;render();}});
 addEventListener('storage',e=>{if(owner.state.status==='writer'&&(e.key===null||SAVE_KEYS.includes(e.key)))owner.invalidate();});
 addEventListener('pagehide',()=>owner.release('此页面已退出保存状态；返回缓存页面时仍只读，请重新载入读取最新档案。'));
 // A stale BFCache document never reacquires silently or commits its old heap.
 addEventListener('pageshow',e=>{if(e.persisted)owner.release('这是返回的旧页面，仅可查看。请重新载入后读取最新存档并尝试取得写入权。');});
 // Disable edit fields and intercept explicit mutation controls before their
 // handlers alter an in-memory draft. Native storage guards remain the final
 // boundary for every write, including asynchronous and unlisted call sites.
 const edits=['#editor [data-field]','#editor [data-add]','#editor [data-remove]','#editor [data-up]','#editor [data-inherit]','#seed','#expedition','#supplies input','#file','#save-a','#save-plan','#update-plan','#bind-plan','#unbind-plan','#delete-plan','#load-plan','#undo-load','#reset','#restore-report','#report-to-a','#challenge','#key-events','[data-comparison-clear]','[data-draft-undo]','[data-adventure]','[data-own-hero]','[data-learn]','[data-untrain]','[data-equip]','[data-assign]','[data-sell]','[data-set-save]','[data-set-apply]','[data-set-delete]','[data-recruit]','[data-swap]','[data-advancement]','[data-reset-advancement]','[data-unlock]','[data-install]','[data-install-default]','[data-apply-companion]','[data-loot-return-confirm]','[data-archive-remove]','[data-archive-rename]','[data-campaign-restore]','[data-harbor-redeem]','[data-report-cycle=claim]','[data-guild=depart]','[data-guild=claim]','[data-guild=reset]','[data-reuse-apply]','[data-equipment-goal]','[data-equipment-goal-clear]','[data-equipment-goal-assign]','[data-equipment-goal-wear]','[data-shoals-chart]','[data-postquest-path]','[data-postquest-deliver]','[data-returnquest-path]','[data-foundry-story-end]','[data-harbor-story-end]','[data-clocktower-story-end]','[data-plan-action=apply]','[data-plan-action=pay]','[data-collect-report]','#challenge','#key-events','#case-defense','#case-delay','#case-room','#case-summon','#case-item','#case-shortage','#case-training','#case-pierce','#archive-start','#case-archive','#bell-options button','#event-start','#case-bell','#rescue-options button','#rescue-start','#scarcity-start','#scarcity-adapted','#survival-start','#survival-brief button','#hospice-start','#hospice-brief button','#role-hunt button','#trial-brief button','#harbor-plan select','#harbor-brief button','#foundry-brief select','#watch-brief button','#courier-brief button','#courier-brief select','#palisade-brief button','#inquest-brief button','#theater-brief button','#shoals-brief button','#shoals-brief select','#scriptorium-brief button','#greenhouse-brief button','#clocktower-brief button','#confluence-brief button','#counterpoint-brief button','#withdraw-at','#breakwater-brief button','#ossuary-brief button','#lockworks-brief button','#trapworks-brief button','#beaconbridge-brief button','[data-guild=retrain]','[data-supply]','[data-capture-save]'].join(',');
 const mark=()=>{if(owner.state.status==='writer')return;for(const n of document.querySelectorAll(edits)){n.setAttribute('aria-disabled','true');if(n.matches('input,select,textarea'))n.disabled=true;}};
 const refuse=e=>{if(owner.state.status==='writer'||!e.target?.closest?.(edits))return;e.preventDefault();e.stopImmediatePropagation();const feedback=document.querySelector('#guild-feedback');if(feedback)feedback.textContent=owner.state.reason;const notice=document.querySelector('#notice');if(notice)notice.textContent=owner.state.reason;box.querySelector('strong')?.focus({preventScroll:true});};
 for(const type of ['click','change','input','submit'])document.addEventListener(type,refuse,true);owner.subscribe(mark);new MutationObserver(mark).observe(document.body,{subtree:true,childList:true});mark();
 render();if(!guarded)for(const n of document.querySelectorAll('header,main'))n.hidden=true;Object.defineProperty(owner,'guardInstalled',{value:guarded});return owner;
}
